   "fast.status.title": "Status",
   "fast.phase.prev": "Previous",
   "fast.phase.next": "Next",
   "fast.phase.fed.range": "0 – 4h",
   "fast.phase.fed.title": "Fed state",
   "fast.phase.fed.desc": "Your body processes the last meal. Insulin is high and glucose from food fuels every cell.",
   "fast.phase.fed.long": "In the first hours after eating, insulin rises and your body uses food glucose as its main fuel. Extra glucose is stored in the liver as glycogen for later use. This is the anabolic phase — building, storing, and repairing.",
   "fast.phase.glycogen.range": "4 – 8h",
   "fast.phase.glycogen.title": "Glycogen burn",
   "fast.phase.glycogen.desc": "Insulin drops. Your liver taps into stored glycogen to keep your blood sugar steady.",
   "fast.phase.glycogen.long": "Blood sugar falls back toward baseline. Your body switches from digesting food to burning stored glycogen. You may feel light hunger — that's your stomach reminding you, not a real energy shortage.",
   "fast.phase.switch.range": "8 – 12h",
   "fast.phase.switch.title": "Switching to fasted mode",
   "fast.phase.switch.desc": "Liver glycogen runs low. Your body begins gluconeogenesis — making glucose from fat and protein.",
   "fast.phase.switch.long": "Around 8 hours after your last meal, glycogen stores start running out. Your body shifts into gluconeogenesis, producing glucose from body fat instead of carbs. You begin burning more calories from fat.",
   "fast.phase.ketosis.range": "12 – 18h",
   "fast.phase.ketosis.title": "Ketosis starts",
   "fast.phase.ketosis.desc": "Glycogen is nearly used up. The liver begins turning fat into ketones — an alternative fuel.",
   "fast.phase.ketosis.long": "Your metabolism transitions into ketosis. Fat is broken down into ketone bodies, an efficient fuel for your brain and muscles. Fat oxidation increases and mental clarity often improves.",
   "fast.phase.deepKeto.range": "18 – 24h",
   "fast.phase.deepKeto.title": "Deep ketosis",
   "fast.phase.deepKeto.desc": "Ketone levels rise and fat burning ramps up. Autophagy — cellular clean-up — starts to kick in.",
   "fast.phase.deepKeto.long": "Ketones become a primary energy source. Growth hormone starts to rise, insulin sensitivity improves, and early autophagy begins — cells start recycling damaged parts.",
   "fast.phase.autophagy.range": "24 – 48h",
   "fast.phase.autophagy.title": "Full autophagy",
   "fast.phase.autophagy.desc": "Cells clean out damaged parts and recycle them. Growth hormone climbs and inflammation drops.",
   "fast.phase.autophagy.long": "Autophagy ramps up: your cells break down and reuse damaged proteins and organelles. Inflammation markers drop, growth hormone surges, and your body enters a deep repair mode.",
   "fast.phase.growth.range": "48 – 72h",
   "fast.phase.growth.title": "Growth hormone peak",
   "fast.phase.growth.desc": "Growth hormone surges up to 5×. Deep cellular reset, insulin sensitivity improves markedly.",
   "fast.phase.growth.long": "Growth hormone peaks — protecting lean muscle mass while your body keeps burning fat. Stem cell activity rises and your immune system starts renewing itself.",
   "fast.phase.reset.range": "72h+",
   "fast.phase.reset.title": "Deep metabolic reset",
   "fast.phase.reset.desc": "Old immune cells are cleared and stem cells rebuild them. A full metabolic reboot.",
   "fast.phase.reset.long": "After 72 hours, your body triggers a deep reset: old immune cells are cleared and new ones are produced from stem cells. Insulin sensitivity, inflammation, and cellular health reach their best point of the fast.",
