   "fast.status.title": "Status",
   "fast.phase.prev": "Vorige",
   "fast.phase.next": "Volgende",
   "fast.phase.fed.range": "0 – 4u",
   "fast.phase.fed.title": "Voedingsfase",
   "fast.phase.fed.desc": "Je lichaam verwerkt de laatste maaltijd. Insuline is hoog en glucose voedt je cellen.",
   "fast.phase.fed.long": "In de eerste uren na het eten stijgt insuline en gebruikt je lichaam glucose uit voeding als brandstof. Extra glucose wordt opgeslagen als glycogeen in je lever. Dit is de anabole fase — opbouwen en opslaan.",
   "fast.phase.glycogen.range": "4 – 8u",
   "fast.phase.glycogen.title": "Glycogeen verbranden",
   "fast.phase.glycogen.desc": "Insuline daalt. Je lever gebruikt opgeslagen glycogeen om je bloedsuiker stabiel te houden.",
   "fast.phase.glycogen.long": "Je bloedsuiker keert terug naar het normale niveau. Je lichaam schakelt van verteren naar het verbranden van opgeslagen glycogeen. Lichte honger kan opkomen — dat is je maag, geen echt energietekort.",
   "fast.phase.switch.range": "8 – 12u",
   "fast.phase.switch.title": "Overschakelen naar vasten",
   "fast.phase.switch.desc": "Glycogeen in de lever raakt op. Je lichaam start gluconeogenese — glucose maken uit vet en eiwit.",
   "fast.phase.switch.long": "Rond 8 uur na je laatste maaltijd raken je glycogeenreserves op. Je lichaam schakelt over op gluconeogenese en maakt glucose uit lichaamsvet in plaats van koolhydraten. Je verbrandt meer calorieën uit vet.",
   "fast.phase.ketosis.range": "12 – 18u",
   "fast.phase.ketosis.title": "Ketose start",
   "fast.phase.ketosis.desc": "Glycogeen is bijna op. De lever zet vet om in ketonen — een alternatieve brandstof.",
   "fast.phase.ketosis.long": "Je stofwisseling gaat over in ketose. Vet wordt afgebroken tot ketolichamen — een efficiënte brandstof voor hersenen en spieren. Vetverbranding neemt toe en mentale helderheid verbetert vaak.",
   "fast.phase.deepKeto.range": "18 – 24u",
   "fast.phase.deepKeto.title": "Diepe ketose",
   "fast.phase.deepKeto.desc": "Ketonen stijgen, vetverbranding neemt toe. Autofagie — celvernieuwing — begint op gang te komen.",
   "fast.phase.deepKeto.long": "Ketonen worden een primaire energiebron. Groeihormoon begint te stijgen, insulinegevoeligheid verbetert en vroege autofagie start — cellen beginnen beschadigde delen te recyclen.",
   "fast.phase.autophagy.range": "24 – 48u",
   "fast.phase.autophagy.title": "Volledige autofagie",
   "fast.phase.autophagy.desc": "Cellen ruimen beschadigde delen op en recyclen ze. Groeihormoon stijgt en ontstekingen dalen.",
   "fast.phase.autophagy.long": "Autofagie schakelt door: je cellen breken beschadigde eiwitten en organellen af en hergebruiken ze. Ontstekingen dalen, groeihormoon piekt en je lichaam gaat in diepe herstelmodus.",
   "fast.phase.growth.range": "48 – 72u",
   "fast.phase.growth.title": "Groeihormoon-piek",
   "fast.phase.growth.desc": "Groeihormoon stijgt tot 5×. Diepe cellulaire reset, insulinegevoeligheid verbetert sterk.",
   "fast.phase.growth.long": "Groeihormoon piekt — beschermt je spiermassa terwijl je vet blijft verbranden. Stamcelactiviteit stijgt en je immuunsysteem begint zichzelf te vernieuwen.",
   "fast.phase.reset.range": "72u+",
   "fast.phase.reset.title": "Diepe metabolische reset",
   "fast.phase.reset.desc": "Oude immuuncellen worden opgeruimd en stamcellen bouwen ze opnieuw op. Volledige metabole reboot.",
   "fast.phase.reset.long": "Na 72 uur triggert je lichaam een diepe reset: oude immuuncellen worden opgeruimd en nieuwe worden aangemaakt vanuit stamcellen. Insulinegevoeligheid, ontstekingen en celgezondheid bereiken hun beste punt van de vast.",
    "common.cancel": "Annuleren",
