   "fast.phase.glycogen.long": "يعود سكر الدم إلى المستوى الطبيعي. ينتقل الجسم من الهضم إلى حرق الجليكوجين المخزن. قد تشعر بجوع خفيف — إنه تذكير من المعدة وليس نقص طاقة حقيقي.",
