   "fast.phase.switch.long": "بعد 8 ساعات تقريبًا من آخر وجبة، تبدأ مخازن الجليكوجين بالنفاد. ينتقل الجسم إلى استحداث السكر وينتج الجلوكوز من الدهون بدل الكربوهيدرات. تزداد السعرات المحروقة من الدهون.",
