   "fast.phase.ketosis.title": "بدء الكيتوزية",
   "fast.phase.ketosis.desc": "شارف الجليكوجين على النفاد. يبدأ الكبد بتحويل الدهون إلى كيتونات كوقود بديل للجسم.",
   "fast.phase.ketosis.long": "ينتقل الأيض إلى الكيتوزية. تُفكَّك الدهون إلى أجسام كيتونية — وقود فعّال للدماغ والعضلات. يزداد حرق الدهون وتتحسن الصفاء الذهني غالبًا.",
   "fast.phase.deepKeto.range": "18 – 24 س",
   "fast.phase.deepKeto.title": "كيتوزية عميقة",
   "fast.phase.deepKeto.desc": "ترتفع مستويات الكيتون ويزداد حرق الدهون. تبدأ الالتهام الذاتي — تنظيف الخلايا.",
   "fast.phase.deepKeto.long": "تصبح الكيتونات مصدر طاقة رئيسيًا. يبدأ هرمون النمو بالارتفاع وتتحسن حساسية الأنسولين ويبدأ الالتهام الذاتي المبكر — تعيد الخلايا تدوير الأجزاء التالفة.",
   "fast.phase.autophagy.range": "24 – 48 س",
   "fast.phase.autophagy.title": "التهام ذاتي كامل",
   "fast.phase.autophagy.desc": "تنظف الخلايا الأجزاء التالفة وتعيد تدويرها. يرتفع هرمون النمو وينخفض الالتهاب.",
   "fast.phase.autophagy.long": "يشتد الالتهام الذاتي: تفكك الخلايا البروتينات والعضيات التالفة وتعيد استخدامها. تنخفض علامات الالتهاب ويرتفع هرمون النمو ويدخل الجسم في وضع الإصلاح العميق.",
   "fast.phase.growth.range": "48 – 72 س",
   "fast.phase.growth.title": "ذروة هرمون النمو",
   "fast.phase.growth.desc": "يرتفع هرمون النمو حتى 5 أضعاف. إعادة ضبط خلوية عميقة.",
   "fast.phase.growth.long": "يبلغ هرمون النمو ذروته — يحمي الكتلة العضلية بينما يستمر حرق الدهون. يرتفع نشاط الخلايا الجذعية ويبدأ الجهاز المناعي بتجديد نفسه.",
   "fast.phase.reset.range": "72 س+",
   "fast.phase.reset.title": "إعادة ضبط أيضي عميقة",
   "fast.phase.reset.desc": "يتم التخلص من الخلايا المناعية القديمة وإعادة بنائها من الخلايا الجذعية.",
   "fast.phase.reset.long": "بعد 72 ساعة، يبدأ جسمك إعادة ضبط عميقة: تُزال الخلايا المناعية القديمة وتُنتج خلايا جديدة من الخلايا الجذعية. تصل حساسية الأنسولين والالتهاب وصحة الخلية إلى أفضل مستوى في فترة الصيام.",
