   "fast.phase.glycogen.title": "Combustion du glycogène",
   "fast.phase.glycogen.desc": "L'insuline baisse. Le foie puise dans le glycogène stocké pour stabiliser la glycémie.",
   "fast.phase.glycogen.long": "La glycémie revient à son niveau de base. Le corps passe de la digestion à la combustion du glycogène stocké. Une légère faim peut apparaître — c'est votre estomac, pas un vrai manque d'énergie.",
   "fast.phase.switch.range": "8 – 12 h",
   "fast.phase.switch.title": "Passage au mode jeûne",
   "fast.phase.switch.desc": "Le glycogène hépatique s'épuise. Le corps démarre la néoglucogenèse à partir de graisses et protéines.",
   "fast.phase.switch.long": "Vers 8 heures après le dernier repas, les réserves de glycogène s'épuisent. Le corps passe à la néoglucogenèse et fabrique du glucose à partir des graisses corporelles plutôt que des glucides. Vous brûlez plus de calories issues des graisses.",
   "fast.phase.ketosis.range": "12 – 18 h",
   "fast.phase.ketosis.title": "Début de cétose",
   "fast.phase.ketosis.desc": "Le glycogène est presque épuisé. Le foie transforme la graisse en cétones — un carburant alternatif.",
   "fast.phase.ketosis.long": "Le métabolisme passe en cétose. La graisse est décomposée en corps cétoniques — un carburant efficace pour le cerveau et les muscles. L'oxydation des graisses augmente et la clarté mentale s'améliore souvent.",
   "fast.phase.deepKeto.range": "18 – 24 h",
   "fast.phase.deepKeto.title": "Cétose profonde",
   "fast.phase.deepKeto.desc": "Les cétones montent, la combustion des graisses s'accélère. L'autophagie démarre.",
   "fast.phase.deepKeto.long": "Les cétones deviennent une source d'énergie primaire. L'hormone de croissance commence à monter, la sensibilité à l'insuline s'améliore et l'autophagie précoce démarre — les cellules recyclent leurs pièces abîmées.",
   "fast.phase.autophagy.range": "24 – 48 h",
   "fast.phase.autophagy.title": "Autophagie complète",
   "fast.phase.autophagy.desc": "Les cellules éliminent et recyclent les parties abîmées. Hormone de croissance en hausse, inflammation en baisse.",
   "fast.phase.autophagy.long": "L'autophagie s'intensifie : vos cellules décomposent et réutilisent protéines et organites endommagés. Les marqueurs d'inflammation chutent, l'hormone de croissance grimpe, votre corps entre en mode réparation profonde.",
   "fast.phase.growth.range": "48 – 72 h",
   "fast.phase.growth.title": "Pic d'hormone de croissance",
   "fast.phase.growth.desc": "L'hormone de croissance grimpe jusqu'à 5×. Réinitialisation cellulaire profonde.",
   "fast.phase.growth.long": "L'hormone de croissance atteint son pic — elle protège la masse musculaire pendant que la combustion des graisses continue. L'activité des cellules souches augmente et le système immunitaire commence à se renouveler.",
   "fast.phase.reset.range": "72 h+",
   "fast.phase.reset.title": "Réinitialisation métabolique profonde",
   "fast.phase.reset.desc": "Les vieilles cellules immunitaires sont éliminées et reconstruites depuis des cellules souches.",
   "fast.phase.reset.long": "Après 72 heures, votre corps déclenche une réinitialisation profonde : les vieilles cellules immunitaires sont éliminées et de nouvelles sont produites à partir des cellules souches. Sensibilité à l'insuline, inflammation et santé cellulaire atteignent leur meilleur point du jeûne.",
