   "fast.status.title": "Status",
   "fast.phase.prev": "Zurück",
   "fast.phase.next": "Weiter",
   "fast.phase.fed.range": "0 – 4 Std.",
   "fast.phase.fed.title": "Sättigungsphase",
   "fast.phase.fed.desc": "Dein Körper verarbeitet die letzte Mahlzeit. Insulin ist hoch, Glukose versorgt jede Zelle.",
   "fast.phase.fed.long": "In den ersten Stunden nach dem Essen steigt Insulin und dein Körper nutzt Glukose aus der Nahrung als Hauptbrennstoff. Überschüssige Glukose wird als Glykogen in der Leber gespeichert. Das ist die anabole Phase — Aufbau und Speicherung.",
   "fast.phase.glycogen.range": "4 – 8 Std.",
   "fast.phase.glycogen.title": "Glykogenverbrennung",
   "fast.phase.glycogen.desc": "Insulin sinkt. Die Leber greift auf gespeichertes Glykogen zurück, um den Blutzucker stabil zu halten.",
   "fast.phase.glycogen.long": "Der Blutzucker fällt auf den Basiswert zurück. Der Körper wechselt vom Verdauen zum Verbrennen von Glykogenspeichern. Leichter Hunger kann auftreten — das ist dein Magen, nicht echter Energiemangel.",
   "fast.phase.switch.range": "8 – 12 Std.",
   "fast.phase.switch.title": "Umschalten in Fastenmodus",
   "fast.phase.switch.desc": "Leberglykogen geht zur Neige. Der Körper startet die Gluconeogenese aus Fett und Protein.",
   "fast.phase.switch.long": "Etwa 8 Stunden nach der letzten Mahlzeit sind die Glykogenspeicher fast leer. Der Körper wechselt in die Gluconeogenese und stellt Glukose aus Körperfett statt Kohlenhydraten her. Du verbrennst mehr Kalorien aus Fett.",
   "fast.phase.ketosis.range": "12 – 18 Std.",
   "fast.phase.ketosis.title": "Ketose beginnt",
   "fast.phase.ketosis.desc": "Glykogen ist fast aufgebraucht. Die Leber wandelt Fett in Ketone um — ein alternativer Brennstoff.",
   "fast.phase.ketosis.long": "Der Stoffwechsel wechselt in Ketose. Fett wird in Ketonkörper zerlegt — ein effizienter Brennstoff für Gehirn und Muskeln. Fettverbrennung nimmt zu und die mentale Klarheit verbessert sich oft.",
   "fast.phase.deepKeto.range": "18 – 24 Std.",
   "fast.phase.deepKeto.title": "Tiefe Ketose",
   "fast.phase.deepKeto.desc": "Ketonspiegel steigen, Fettverbrennung nimmt zu. Autophagie — Zellreinigung — setzt ein.",
   "fast.phase.deepKeto.long": "Ketone werden zur primären Energiequelle. Wachstumshormon steigt, Insulinempfindlichkeit verbessert sich und frühe Autophagie startet — Zellen recyceln beschädigte Teile.",
   "fast.phase.autophagy.range": "24 – 48 Std.",
   "fast.phase.autophagy.title": "Volle Autophagie",
   "fast.phase.autophagy.desc": "Zellen räumen beschädigte Teile auf und recyceln sie. Wachstumshormon steigt, Entzündungen sinken.",
   "fast.phase.autophagy.long": "Autophagie schaltet hoch: Zellen bauen beschädigte Proteine und Organellen ab und wiederverwenden sie. Entzündungsmarker sinken, Wachstumshormon steigt, dein Körper geht in den tiefen Reparaturmodus.",
   "fast.phase.growth.range": "48 – 72 Std.",
   "fast.phase.growth.title": "Wachstumshormon-Peak",
   "fast.phase.growth.desc": "Wachstumshormon steigt bis 5×. Tiefe Zellerneuerung, deutlich bessere Insulinempfindlichkeit.",
   "fast.phase.growth.long": "Wachstumshormon erreicht den Peak — schützt Muskelmasse, während die Fettverbrennung weiterläuft. Stammzellaktivität steigt und das Immunsystem beginnt sich zu erneuern.",
   "fast.phase.reset.range": "72 Std.+",
   "fast.phase.reset.title": "Tiefer Stoffwechsel-Reset",
   "fast.phase.reset.desc": "Alte Immunzellen werden abgebaut und durch Stammzellen neu aufgebaut.",
   "fast.phase.reset.long": "Nach 72 Stunden löst dein Körper einen tiefen Reset aus: alte Immunzellen werden entfernt und neue aus Stammzellen produziert. Insulinempfindlichkeit, Entzündung und Zellgesundheit erreichen ihren besten Punkt der Fastenperiode.",
