   "fast.status.title": "Estado",
   "fast.phase.prev": "Anterior",
   "fast.phase.next": "Siguiente",
   "fast.phase.fed.range": "0 – 4 h",
   "fast.phase.fed.title": "Estado alimentado",
   "fast.phase.fed.desc": "Tu cuerpo procesa la última comida. La insulina está alta y la glucosa alimenta cada célula.",
   "fast.phase.fed.long": "En las primeras horas tras comer, la insulina sube y tu cuerpo usa la glucosa de los alimentos como combustible principal. El exceso se almacena como glucógeno en el hígado. Es la fase anabólica — construcción y almacenamiento.",
   "fast.phase.glycogen.range": "4 – 8 h",
   "fast.phase.glycogen.title": "Quema de glucógeno",
   "fast.phase.glycogen.desc": "La insulina baja. El hígado usa el glucógeno almacenado para mantener estable el azúcar.",
   "fast.phase.glycogen.long": "El azúcar en sangre vuelve al nivel base. El cuerpo pasa de digerir a quemar glucógeno almacenado. Puede aparecer un hambre ligera — es tu estómago, no una falta real de energía.",
   "fast.phase.switch.range": "8 – 12 h",
   "fast.phase.switch.title": "Cambio al modo ayuno",
   "fast.phase.switch.desc": "El glucógeno del hígado se agota. El cuerpo inicia la gluconeogénesis a partir de grasa y proteína.",
   "fast.phase.switch.long": "Cerca de 8 horas después de la última comida, las reservas de glucógeno se agotan. El cuerpo pasa a la gluconeogénesis y produce glucosa a partir de la grasa corporal en lugar de carbohidratos. Quemas más calorías de grasa.",
   "fast.phase.ketosis.range": "12 – 18 h",
   "fast.phase.ketosis.title": "Inicio de cetosis",
   "fast.phase.ketosis.desc": "El glucógeno casi se agota. El hígado convierte la grasa en cetonas — un combustible alternativo.",
   "fast.phase.ketosis.long": "El metabolismo entra en cetosis. La grasa se descompone en cuerpos cetónicos — combustible eficiente para cerebro y músculos. La oxidación de grasa aumenta y la claridad mental suele mejorar.",
   "fast.phase.deepKeto.range": "18 – 24 h",
   "fast.phase.deepKeto.title": "Cetosis profunda",
   "fast.phase.deepKeto.desc": "Los niveles de cetonas suben y la quema de grasa aumenta. Comienza la autofagia — limpieza celular.",
   "fast.phase.deepKeto.long": "Las cetonas se convierten en fuente primaria de energía. La hormona del crecimiento comienza a subir, la sensibilidad a la insulina mejora y arranca la autofagia temprana — las células reciclan partes dañadas.",
   "fast.phase.autophagy.range": "24 – 48 h",
   "fast.phase.autophagy.title": "Autofagia completa",
   "fast.phase.autophagy.desc": "Las células limpian y reciclan partes dañadas. La hormona del crecimiento sube y la inflamación baja.",
   "fast.phase.autophagy.long": "La autofagia se intensifica: las células descomponen y reutilizan proteínas y orgánulos dañados. Los marcadores de inflamación caen, la hormona del crecimiento sube y el cuerpo entra en modo de reparación profunda.",
   "fast.phase.growth.range": "48 – 72 h",
   "fast.phase.growth.title": "Pico de hormona de crecimiento",
   "fast.phase.growth.desc": "La hormona del crecimiento sube hasta 5×. Reinicio celular profundo.",
   "fast.phase.growth.long": "La hormona del crecimiento alcanza su pico — protege la masa muscular mientras sigue la quema de grasa. La actividad de las células madre aumenta y el sistema inmunitario empieza a renovarse.",
   "fast.phase.reset.range": "72 h+",
   "fast.phase.reset.title": "Reinicio metabólico profundo",
   "fast.phase.reset.desc": "Las viejas células inmunitarias se eliminan y se reconstruyen desde células madre.",
   "fast.phase.reset.long": "Tras 72 horas, tu cuerpo desencadena un reinicio profundo: las viejas células inmunitarias se eliminan y se producen nuevas a partir de células madre. Sensibilidad a la insulina, inflamación y salud celular alcanzan su mejor punto del ayuno.",
